(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.CatReport=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const related={overbite:['openTeeth'],molar:['molarMm'],spacing:['closeSpace'],u1sn:['correctU1'],eline:['correctEline'],gummy:['correctGummy']};
  function filename(data){return 'CAT-CAT_'+String(data.input.caseId||data.caseName||'report').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,80);}
  function build(data,model,{t=key=>key,locale='en-US'}={}){
    if(!data?.results?.valid)throw new Error('Incomplete report');
    const lang=['en','zh-Hant','zh-Hans','ja','ar'].includes(data.language)?data.language:'en',dir=lang==='ar'?'rtl':'ltr';
    const fmt=n=>Number(n).toLocaleString(locale,{maximumFractionDigits:2});
    function value(field,raw){if(raw===null||raw===undefined||raw==='')return t('未填寫');if(field?.type==='check')return t(raw?'有':'無');if(field?.options)return t(field.options.find(o=>o[0]===String(raw))?.[1]||String(raw));return (field?.type==='text'?String(raw):fmt(raw))+(field?.unit?' '+t(field.unit):'');}
    const field=id=>model.fields.find(f=>f.id===id);
    const inputCell=entry=>[entry.id,...(related[entry.id]||[])].filter(id=>field(id)&&model.active(field(id),data.input)).map((id,i)=>`<div>${i?esc(t(field(id).label))+': ':''}<bdi>${esc(value(field(id),data.input[id]))}</bdi></div>`).join('');
    const rows=(group)=>data.results.entries.filter(e=>e.group===group.id).map(e=>`<tr><td>${esc(e.label)}</td><td>${inputCell(e)}</td><td class="numeric">${fmt(e.score)}</td></tr>`).join('');
    const groups=model.groups.filter(g=>g.id!=='case');
    const header=(labels)=>'<thead><tr>'+labels.map(label=>'<th>'+esc(t(label))+'</th>').join('')+'</tr></thead>';
    const summary=groups.map(g=>`<div><span>${esc(t(g.title))}</span><strong>${fmt(data.results.domains[g.id])}</strong><div class="bar"><i style="width:${data.results.baseline?100*data.results.domains[g.id]/data.results.baseline:0}%"></i></div></div>`).join('');
    let comparison='';
    if(data.reference?.results?.valid){const ref=data.reference,changes=ref.difference?.fields||[];comparison=`<section><h2>${esc(t('病例比較'))}</h2><p>${esc(t('參考病例'))}: <bdi>${esc(ref.input.caseId)}</bdi> · ${fmt(ref.results.baseline)} ${esc(t('分'))} → ${esc(t('目前病例'))}: ${fmt(data.results.baseline)} ${esc(t('分'))} (${ref.difference?.baseline>0?'+':''}${fmt(data.results.baseline-ref.results.baseline)})</p><table>${header(['變更項目','參考值','目前值'])}<tbody>${changes.length?changes.map(f=>`<tr><td>${esc(f.label)}</td><td><bdi>${esc(value(field(f.id),f.before))}</bdi></td><td><bdi>${esc(value(field(f.id),f.after))}</bdi></td></tr>`).join(''):`<tr><td colspan="3">${esc(t('輸入未變更'))}</td></tr>`}</tbody></table><p class="note">${esc(t('分數差異反映項目計分，不代表治療效果。'))}</p></section>`;}
    let sources='';
    if(data.importedMeasurements?.length)sources=`<section><h2>${esc(t('匯入測量來源'))}</h2><table>${header(['測量項目','確認值','來源位置'])}<tbody>${data.importedMeasurements.map(p=>`<tr><td>${esc(p.label||t(field(p.field)?.label||p.field))}</td><td><bdi>${esc(value(field(p.field),p.value))}</bdi></td><td>${esc((p.origins||[]).map(o=>[o.section,o.page?t('頁碼 {pages}',{pages:o.page}):o.line?t('來源行 {line}',{line:o.line}):''].filter(Boolean).join(' · ')).join('; ')||'—')}</td></tr>`).join('')}</tbody></table></section>`;
    return `<!doctype html><html lang="${lang}" dir="${dir}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(filename(data))}</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f0f8;color:#2e2538;font:15px/1.65 system-ui,-apple-system,"Noto Sans",sans-serif}.toolbar{position:sticky;top:0;z-index:2;display:flex;gap:12px;align-items:center;flex-wrap:wrap;background:#2d203e;color:white;padding:14px 24px}.toolbar button{font:inherit;cursor:pointer;border:0;border-radius:6px;background:white;color:#4e3373;padding:9px 16px}.toolbar p{margin:0;flex:1;font-size:13px}.report{max-width:950px;margin:28px auto;background:white;padding:40px;border:1px solid #ded2e7}.brand{font-size:13px;letter-spacing:2px;color:#69409a;font-weight:750}h1{font-size:28px;margin:8px 0 18px}h2{font-size:19px;margin:26px 0 12px;color:#4e3373}.metadata{display:grid;grid-template-columns:1fr 1fr;gap:6px 20px;border-block:1px solid #e3d9eb;padding:16px 0}.metadata p{margin:0}.note{font-size:12px;color:#665573}.total{display:flex;align-items:center;gap:25px;margin:24px 0;background:#eee5f7;padding:22px;border-radius:8px}.total strong{font-size:48px;line-height:1.2;color:#69409a}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.summary strong{display:block;font-size:27px;color:#69409a}.bar{height:6px;background:#eee5f7;margin-top:8px}.bar i{display:block;height:100%;background:#69409a}table{width:100%;border-collapse:collapse;font-size:13px;table-layout:fixed}th,td{text-align:start;border-bottom:1px solid #ddd2e7;padding:10px 12px;vertical-align:top;overflow-wrap:anywhere}th{background:#eee5f7;color:#4e3373}th:first-child{width:38%}th:last-child{width:17%}.numeric{text-align:end;font-variant-numeric:tabular-nums;font-weight:650}tbody tr:nth-child(even){background:#faf7fd}thead{display:table-header-group}tr{break-inside:avoid}footer{border-top:1px solid #ddd2e7;margin-top:25px;padding-top:14px;font-size:11px;color:#665573}footer a{color:inherit;overflow-wrap:anywhere}h2{break-after:avoid}.total,.summary,.metadata{break-inside:avoid}bdi{unicode-bidi:isolate}@media(max-width:600px){.report{margin:0;padding:22px 16px}.metadata{grid-template-columns:1fr}.summary{gap:10px}.summary span{font-size:12px}th,td{padding:8px 5px}.toolbar{padding:12px}.toolbar p{flex-basis:100%}}@page{size:A4;margin:16mm 14mm}@media print{body{background:white;font-size:12px}.toolbar{display:none}.report{max-width:none;margin:0;padding:0;border:0}h1{font-size:24px}.total{padding:14px;margin:18px 0}.total strong{font-size:38px}th,td{padding:7px 9px}table{font-size:11px}a{text-decoration:none}.summary{gap:18px}footer{font-size:10px}}
</style></head><body><div class="toolbar"><button id="printReport">${esc(t('儲存 PDF／列印'))}</button><button id="closeReport">${esc(t('關閉報告'))}</button><p>${esc(t('在列印視窗選擇「另存為 PDF」，即可保存表格報告。'))}</p></div><main class="report"><div class="brand">CAT-CAT</div><h1>${esc(t('病例評估報告'))}</h1><div class="metadata"><p>${esc(t('病例名稱'))}: <bdi>${esc(data.caseName||data.input.caseId)}</bdi></p><p>${esc(t('病例識別'))}: <bdi>${esc(data.input.caseId)}</bdi></p><p>${esc(t('年齡'))}: <bdi>${esc(value(field('age'),data.input.age))}</bdi></p><p>${esc(t('匯出時間'))}: <bdi>${esc(new Date(data.createdAt).toLocaleString(locale))}</bdi></p></div>${data.caseKind==='example'?`<p class="note">${esc(t('合成示例：此報告用於展示計分。'))}</p>`:''}<div class="total"><strong>${fmt(data.results.baseline)}</strong><div>${esc(t('CAT-CAT 總分'))}<p class="note">${esc(t('文獻項目加總 · 無固定滿分'))}</p></div></div><div class="summary">${summary}</div>${groups.map(g=>`<section><h2>${esc(t(g.title))} · ${fmt(data.results.domains[g.id])} ${esc(t('分'))}</h2><table>${header(['計分項目','病例輸入','分數'])}<tbody>${rows(g)}</tbody></table></section>`).join('')}${comparison}${sources}<footer><p>${esc(t('計分版本'))}: <bdi>${esc(data.version)}</bdi></p><p>${esc(t('共同計分來源'))}: <a href="https://doi.org/10.1186/s12903-020-01300-6">${esc(data.baselineSource)}</a></p><p>Email: <a href="mailto:leticiakuang@gmail.com">leticiakuang@gmail.com</a></p></footer></main></body></html>`;
  }
  function open(data,model,options){
    const existing=document.getElementById('catReportDialog');if(existing)existing.close();
    const dialog=document.createElement('dialog');dialog.id='catReportDialog';dialog.setAttribute('aria-label',options.t('病例評估報告'));dialog.style.cssText='width:min(1100px,96vw);height:92vh;max-width:96vw;max-height:92vh;padding:0;border:1px solid #d9c9e5;border-radius:10px;box-shadow:0 12px 60px #2d203e55;background:white';
    const frame=document.createElement('iframe');frame.title=options.t('病例評估報告');frame.style.cssText='display:block;width:100%;height:100%;border:0';frame.setAttribute('sandbox','allow-same-origin allow-modals');
    frame.addEventListener('load',()=>{const doc=frame.contentDocument;doc.getElementById('closeReport').addEventListener('click',()=>dialog.close());doc.getElementById('printReport').addEventListener('click',()=>{const title=document.title;document.title=filename(data);try{frame.contentWindow.focus();frame.contentWindow.print();}finally{document.title=title;}});});
    frame.srcdoc=build(data,model,options);dialog.appendChild(frame);dialog.addEventListener('close',()=>dialog.remove());document.body.appendChild(dialog);dialog.showModal();return true;
  }
  return {build,open,filename};
});
